#include <chrono>
#include <cstring>
#include <filesystem>
#include <iostream>
#include "ddb/recovery/undo_engine.h"
int main(){try{auto db=std::filesystem::temp_directory_path()/"ddb_undo_benchmark.db";std::error_code e;std::filesystem::remove(db,e);std::filesystem::remove(db.string()+".wal",e);ddb::storage::PageManager pages(db);ddb::storage::LogManager log(db.string()+".wal");ddb::buffer::BufferPoolManager pool(pages,128,&log);constexpr std::size_t count=50;(void)log.append_begin(1);for(std::size_t i=0;i<count;++i){auto id=pages.allocate_page();std::vector<std::byte> after(ddb::storage::kPagePayloadSize,std::byte{1});ddb::storage::PhysicalMutation m{id,ddb::storage::MutationKind::PayloadWrite,i,std::vector<std::byte>(ddb::storage::kPagePayloadSize),std::move(after)};auto lsn=log.append_physical_mutation(1,m);auto*p=pool.fetch_page(id);std::memset(p->data(),1,p->payload_size());p->set_lsn(lsn);pool.unpin_page(id,true);}log.flush();auto state=ddb::recovery::RecoveryAnalyzer::analyze(log);ddb::recovery::ReplayContext replay(pages,pool);auto start=std::chrono::steady_clock::now();auto metrics=ddb::recovery::UndoEngine::run(state,replay);auto us=std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now()-start).count();std::cout<<"UNDO benchmark: wal_bytes="<<state.metrics.wal_bytes_scanned<<", transactions="<<metrics.incomplete_transactions<<", mutations="<<metrics.mutations_considered<<", undone="<<metrics.mutations_undone<<", skipped="<<metrics.mutations_skipped<<", pages="<<metrics.pages_touched<<", duration_us="<<us<<"\n";}catch(const std::exception&x){std::cerr<<x.what()<<'\n';return 1;}}
